// A cohort with nine shared four-period blocks needs exactly 36 shared slots.
// Core sessions occupy the remaining four; each option is placed as two doubles.
export function generateOptionGrid(original,api,{maxNodes=5000}={}){
 if(!original.optionCollection)return null;const official=original.optionBlocks.filter(b=>/^option-(10|11)-[A-I]$/.test(b.id));if(official.length!==9)return null;let nodes=0;
 const core=original.optionBlocks.filter(b=>b.id.startsWith('choice-core-')),year=original.groups[0]?.year,peDay=original.schoolPolicy.peDays[year],at=(p,id,day,period)=>{for(const roomId of p.activities.find(a=>id.startsWith(a.id+'#'))?.roomIds||[]){if(++nodes>maxNodes)return null;try{return api.move(p,id,{day,period,roomId});}catch{}}return null;};
 for(const peStart of ['7','2','4','5','3','6']){let p=structuredClone(original);p.placements={};let failed=false;for(const subject of ['assembly','pshe','pe']){const block=core.find(b=>b.subjectId===subject);if(!block){failed=true;break;}const next=at(p,block.activityIds[0]+'#1',subject==='pe'?peDay:'mon',subject==='assembly'?'1':subject==='pshe'?'2':peStart);if(!next){failed=true;break;}p=next;}if(failed||nodes>maxNodes)continue;
 const occupied=new Set(Object.entries(p.placements).flatMap(([id,pos])=>{const a=p.activities.find(a=>id.startsWith(a.id+'#')),start=p.periods.findIndex(x=>x.id===pos.period);return p.periods.slice(start,start+a.duration).map(x=>pos.day+'|'+x.id);})),pairs=[];for(const d of p.days){const free=p.periods.filter(x=>!occupied.has(d.id+'|'+x.id));if(free.length%2){failed=true;break;}for(let n=0;n<free.length;n+=2){if(p.periods.indexOf(free[n+1])-p.periods.indexOf(free[n])!==1){failed=true;break;}pairs.push({day:d.id,first:free[n].id,second:free[n+1].id});}}if(failed||pairs.length!==18)continue;
 const counts=new Map(official.map(b=>[b.id,0])),days=new Map(official.map(b=>[b.id,new Set()]));
 function search(index,plan){if(index===pairs.length)return plan;if(nodes>=maxNodes)return null;const pair=pairs[index],choices=official.filter(b=>counts.get(b.id)<2&&!days.get(b.id).has(pair.day)).sort((a,b)=>counts.get(a.id)-counts.get(b.id)||a.id.localeCompare(b.id));for(const b of choices){const n=counts.get(b.id),first=at(plan,b.activityIds[0]+'#'+(n*2+1),pair.day,pair.first);if(!first)continue;const second=at(first,b.activityIds[0]+'#'+(n*2+2),pair.day,pair.second);if(!second)continue;counts.set(b.id,n+1);days.get(b.id).add(pair.day);const done=search(index+1,second);if(done)return done;counts.set(b.id,n);days.get(b.id).delete(pair.day);}return null;}
 const done=search(0,p);if(done){const report=api.validate(done);if(report.complete)return{project:done,report:{...report,nodes,attempts:1,stopped:'complete',algorithm:'Model 3 cohort blocking with paired periods and validated core sessions.'}};}
 }
 return null;
}
